export interface Orden {
  id: number;
  numero: string;
}

function authHeader(authToken: string): string {
  return `Bearer ${authToken.replace(/^Basic\s+/i, '')}`;
}

export async function listarOrdenes(authToken: string): Promise<Orden[]> {
  const r = await fetch('/api/ordenes', {
    headers: { Authorization: authHeader(authToken) },
  });
  if (!r.ok) {
    throw new Error(`HTTP ${r.status}`);
  }
  return r.json();
}

