export interface Orden {
  id: number;
  numero: string;
}

const PLUGIN_NAME = 'acmebackend';

function authHeader(authToken: string): string {
  return `Bearer ${authToken.replace(/^Basic\s+/i, '')}`;
}

export async function listarOrdenes(pluginApiUrl: string, authToken: string): Promise<Orden[]> {
  const r = await fetch(`${pluginApiUrl}/${PLUGIN_NAME}/ordenes`, {
    headers: { Authorization: authHeader(authToken) },
  });
  if (!r.ok) {
    throw new Error(`HTTP ${r.status}`);
  }
  return r.json();
}
